// Generates src/styles/tokens.css from design/brand-tokens.json.
// Mirrors the brand guide's own buildCss() so variable names match the guide's
// developer handoff exactly. Never edit tokens.css by hand.
import { readFileSync, writeFileSync, mkdirSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const T = JSON.parse(readFileSync(resolve(root, 'design/brand-tokens.json'), 'utf8'));

const L = [
  '/* GENERATED by scripts/build-tokens.mjs from design/brand-tokens.json. Do not edit. */',
  '/* Source: SAHA Residences brand guide v1.0, section 11. Mobile-first; desktop type from 768px. */',
  ':root {',
];
for (const [k, v] of Object.entries(T.color)) L.push(`  --color-${k}: ${v};`);
for (const [k, v] of Object.entries(T.font)) L.push(`  --font-${k}: ${v};`);
for (const [k, v] of Object.entries(T.type)) {
  L.push(
    `  --type-${k}-family: var(--font-${v.family});`,
    `  --type-${k}-weight: ${v.weight};`,
    `  --type-${k}-size: ${v.size[0]};`,
    `  --type-${k}-line: ${v.line[0]};`,
    `  --type-${k}-tracking: ${v.tracking};`,
  );
}
for (const [k, v] of Object.entries(T.space)) L.push(`  --space-${k}: ${v};`);
for (const [k, v] of Object.entries(T.radius)) L.push(`  --radius-${k}: ${v};`);
for (const [k, v] of Object.entries(T.elevation)) L.push(`  --elevation-${k}: ${v};`);
for (const [k, v] of Object.entries(T.container)) L.push(`  --container-${k}: ${v};`);
for (const [k, v] of Object.entries(T.control)) L.push(`  --control-${k}: ${v};`);
L.push('}', '', `/* Breakpoints: ${Object.entries(T.breakpoint).map(([k, v]) => `${k} ${v}`).join(', ')} */`);
L.push(`@media (min-width: ${T.breakpoint.md}) {`, '  :root {');
for (const [k, v] of Object.entries(T.type)) {
  if (v.size[0] !== v.size[1] || v.line[0] !== v.line[1]) {
    L.push(`    --type-${k}-size: ${v.size[1]};`, `    --type-${k}-line: ${v.line[1]};`);
  }
}
L.push('  }', '}', '');

const out = resolve(root, 'src/styles/tokens.css');
mkdirSync(dirname(out), { recursive: true });
writeFileSync(out, L.join('\n'));
console.log(`tokens: wrote ${out}`);
